// Which network a link belongs to, or '' when it is not a known one.
function quickpress_social_network_for( $url ) {
	if ( 0 === strpos( $url, 'mailto:' ) ) {
		return 'mail';
	}
	$host = strtolower( (string) wp_parse_url( $url, PHP_URL_HOST ) );
	$host = preg_replace( '/^(www|m)\./', '', $host );
	if ( '' === $host ) {
		return '';
	}
	foreach ( quickpress_social_networks() as $key => $network ) {
		foreach ( $network['hosts'] as $known ) {
			if ( $host === $known || substr( $host, -strlen( '.' . $known ) ) === '.' . $known ) {
				return $key;
			}
		}
	}
	// Feeds: this site's feed or any address ending in /feed or /rss.
	$path = (string) wp_parse_url( $url, PHP_URL_PATH );
	if ( preg_match( '#/(feed|rss)/?$#i', $path ) ) {
		return 'rss';
	}
	return '';
}

// Swap the link text for the icon, in the Footer Menu only.
function quickpress_social_icon_links( $item_output, $item, $depth, $args ) {
	if ( empty( $args->theme_location ) || 'footer' !== $args->theme_location || ! apply_filters( 'quickpress_social_icons', true ) ) {
		return $item_output;
	}
	$key = quickpress_social_network_for( $item->url );
	if ( ! $key ) {
		return $item_output;
	}
	$networks = quickpress_social_networks();
	$icon     = '<svg class="qp-icon" viewBox="' . esc_attr( $networks[ $key ]['viewbox'] ) . '" aria-hidden="true" focusable="false"><path d="' . esc_attr( $networks[ $key ]['path'] ) . '"/></svg>';
	$label    = '<span class="screen-reader-text">' . esc_html( $networks[ $key ]['label'] ) . '</span>';
	return preg_replace( '#(<a\b[^>]*>).*?(</a>)#s', '$1' . $icon . $label . '$2', $item_output, 1 );
}
add_filter( 'walker_nav_menu_start_el', 'quickpress_social_icon_links', 10, 4 );

// A class on icon items, so they sit in a neat row.
function quickpress_social_icon_class( $classes, $item, $args ) {
	if ( ! empty( $args->theme_location ) && 'footer' === $args->theme_location && apply_filters( 'quickpress_social_icons', true ) && quickpress_social_network_for( $item->url ) ) {
		$classes[] = 'qp-social';
	}
	return $classes;
}
add_filter( 'nav_menu_css_class', 'quickpress_social_icon_class', 10, 3 );
